text:
Here's your water tracker. Tap a glass to fill it, and tap the last filled glass to undo. It resets each day and tries to remember today's count on this PC.

```page
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Water tracker</title>
<style>
  body { font-family: Segoe UI, sans-serif; background: #eef6fb; color: #17324d; margin: 0; padding: 24px; text-align: center; }
  h1 { font-size: 22px; margin: 0 0 4px; }
  #date { color: #5a7690; font-size: 14px; margin-bottom: 16px; }
  #count { font-size: 40px; font-weight: 600; margin: 8px 0; }
  #msg { min-height: 22px; margin-bottom: 16px; }
  #bar { height: 10px; background: #d3e4f0; border-radius: 6px; max-width: 360px; margin: 0 auto 20px; overflow: hidden; }
  #fill { height: 100%; width: 0; background: #2f8fd8; transition: width .3s; }
  #glasses { display: grid; grid-template-columns: repeat(4, 64px); gap: 12px; justify-content: center; margin-bottom: 20px; }
  .glass { width: 64px; height: 80px; border: 3px solid #2f8fd8; border-radius: 4px 4px 14px 14px; background: #fff; cursor: pointer; padding: 0; position: relative; overflow: hidden; }
  .glass.on { background: #7cc4f2; }
  .glass:focus-visible { outline: 3px solid #17324d; }
  button.ctl { background: #2f8fd8; color: #fff; border: 0; border-radius: 8px; padding: 8px 16px; font-size: 14px; cursor: pointer; margin: 0 4px; }
  button.alt { background: #fff; color: #17324d; border: 1px solid #9bb8cc; }
</style>
</head>
<body>
  <h1>Water tracker</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <button class="ctl" id="add">+ Add a glass</button>
  <button class="ctl alt" id="reset">Reset today</button>
<script>
  var GOAL = 8;
  var today = new Date();
  var key = "water-" + today.getFullYear() + "-" + (today.getMonth() + 1) + "-" + today.getDate();
  var n = 0;
  try { n = parseInt(localStorage.getItem(key) || "0", 10) || 0; } catch (e) {}
  document.getElementById("date").textContent = today.toDateString();

  var wrap = document.getElementById("glasses");
  var glasses = [];
  for (var i = 0; i < GOAL; i++) {
    (function (i) {
      var b = document.createElement("button");
      b.className = "glass";
      b.setAttribute("aria-label", "Glass " + (i + 1));
      b.onclick = function () { n = (n === i + 1) ? i : i + 1; render(); };
      wrap.appendChild(b);
      glasses.push(b);
    })(i);
  }

  function render() {
    for (var i = 0; i < GOAL; i++) glasses[i].className = "glass" + (i < n ? " on" : "");
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    var m = n >= GOAL ? "Goal reached. Well done!" : n === 0 ? "Start with your first glass." : (GOAL - n) + " to go.";
    document.getElementById("msg").textContent = m;
    try { localStorage.setItem(key, String(n)); } catch (e) {}
  }

  document.getElementById("add").onclick = function () { n++; render(); };
  document.getElementById("reset").onclick = function () { n = 0; render(); };
  render();
</script>
</body>
</html>
```

Going past 8 glasses is allowed with the add button. The bar stops at your goal.
